{"command":"python3 << 'EOF'
import pickle

# Try all files with zero padding (01-10)
for i in range(1, 11):
    filename = f"/tmp/model_{i:02d}.pkl"
    try:
        with open(filename, 'rb') as f:
            data = pickle.load(f)
            print(f"sub_{i:02d} (model_{i:02d}.pkl): val_accuracy={data.get('val_accuracy', 'MISSING')}, id={data.get('id', 'N/A')}, framework={data.get('framework', 'N/A')}")
    except Exception as e:
        print(f"sub_{i:02d} (model_{i:02d}.pkl): ERROR - {e}")
EOF
"}
